import fs from 'node:fs';
import net from 'node:net';
import {createHash} from 'node:crypto';
const source="C:\\Users\\steven\\AppData\\Local\\Temp\\odin-native-diagnostic-w41tufu8\\projects\\java_diagnostic\\src\\fixture\\Greeter.java";const outside="E:\\odin\\.odin\\language-sandbox-v3-outside-27dcoyez\\outside-sentinel.txt";
const positive="C:\\Users\\steven\\AppData\\Local\\Temp\\odin-native-diagnostic-w41tufu8\\backend-cache\\java_diagnostic\\native-positive-write.txt";const policy="C:\\Users\\steven\\AppData\\Local\\Temp\\odin-native-diagnostic-w41tufu8\\policies\\fixed-policy.json";
const checks=[];const denied=(name,action)=>{try{action();checks.push({name,status:'FAIL'});}catch(error){checks.push({name,status:'PASS',error:error.code});}};
checks.push({name:'permitted_source_read',status:createHash('sha256').update(fs.readFileSync(source)).digest('hex')==="c237ba9235182698ee92d23ab1a690b1e34e80232cd824329cee5090350e8cab"?'PASS':'FAIL'});
fs.writeFileSync(positive,'explicit-private-write');checks.push({name:'explicit_writable_positive',status:fs.readFileSync(positive,'utf8')==='explicit-private-write'?'PASS':'FAIL'});
denied('outside_content_read',()=>fs.readFileSync(outside));
denied('outside_overwrite',()=>fs.writeFileSync(outside,'denied'));
denied('readonly_source_overwrite',()=>fs.writeFileSync(source,'denied'));
denied('readonly_source_create',()=>fs.writeFileSync(source+'.forbidden','denied'));
denied('protected_policy_read',()=>fs.readFileSync(policy));
for(const path of ["E:\\"]){checks.push({name:'volume_metadata_query',status:fs.statSync(path).isDirectory()?'PASS':'FAIL'});}
const loopbackDenied=await new Promise(resolve=>{const socket=net.createConnection({host:'127.0.0.1',port:60386});socket.once('connect',()=>{socket.destroy();resolve(false);});socket.once('error',()=>resolve(true));socket.setTimeout(700,()=>{socket.destroy();resolve(true);});});
checks.push({name:'loopback_connection_denied',status:loopbackDenied?'PASS':'FAIL'});
console.log(JSON.stringify({checks}));process.exit(checks.every(c=>c.status==='PASS')?0:1);
